#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<char> isComposite(n + 1, 0);
    long long sum = 0;
    for (int i = 2; i <= n; i++) {
        if (isComposite[i]) continue;
        sum += i;
        for (long long j = (long long)i * i; j <= n; j += i) isComposite[j] = 1;
    }
    cout << sum << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> fac;
    int x = n;
    for (int d = 2; (long long)d * d <= x; d++) {
        if (x % d == 0) {
            fac.push_back(d);
            while (x % d == 0) x /= d;   // 除尽，保证质因子不重复输出
        }
    }
    if (x > 1) fac.push_back(x);
    for (size_t i = 0; i < fac.size(); i++) {
        if (i) cout << " ";
        cout << fac[i];
    }
    cout << endl;
    return 0;
}

