#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    int cur = 0, best = 0;
    bool first = true;
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        if (first) { cur = best = x; first = false; }
        else { cur = max(x, cur + x); best = max(best, cur); }
    }
    cout << best << endl;
    return 0;
}

