#include <bits/stdc++.h>
using namespace std;

int main() {
    for (int x = 100; x <= 333; x++) {
        int a = x, b = 2 * x, c = 3 * x;
        if (c > 999) break;
        int mask = 0;
        bool ok = true;
        for (int v : {a, b, c}) {
            int t = v;
            while (t) {
                int d = t % 10;
                if (d == 0) { ok = false; break; }
                if (mask & (1 << (d - 1))) { ok = false; break; }
                mask |= 1 << (d - 1);
                t /= 10;
            }
            if (!ok) break;
        }
        if (ok && __builtin_popcount(mask) == 9) {
            cout << a << " " << b << " " << c << endl;
        }
    }
    return 0;
}

